message:
Fix index.html loading game module. (#6)

https://chat.openai.com/share/aaac1a99-fcff-42ba-b441-06181a26427d

Getting this error in the browser
caught SyntaxError: Unexpected token 'export' - game.js: 1

```
game.js
export default class Game {
    constructor() {
        this.user = this.getUser();
        this.initialize();
    }

    startPlaying() {
        var rikishi = document.querySelector('#rikishi').value;
        var picks = this.getPicks();
        var message = "You selected: " + rikishi + "\nPrevious Picks: " + JSON.stringify(picks);
        this.updatePicks(rikishi); // Update the picks with the new selection
        return message;
    }

    getUser() {
        // get user from local storage
        var user = localStorage.getItem('user');
        if (!user) {
            user = 'admin';
            localStorage.setItem('user', user);
        }
        return user;
    }

    getPicks() {
        var picks = JSON.parse(localStorage.getItem(this.user));
        if (!picks) {
            picks = {};
        }
        return picks;
    }

    updatePicks(rikishi) {
        var picks = this.getPicks();
        var currentContest = new Date().getMonth();
        if ([0, 2, 4, 6, 8, 10].includes(currentContest)) {
            var contestName = new Date().toLocaleString('default', { month: 'long' }) + ' ' + new Date().getFullYear();
            picks[contestName] = rikishi;
            localStorage.setItem(this.user, JSON.stringify(picks));
        }
    }

    switchUser() {
        var newUser = document.querySelector('#userSwitch').value;
        localStorage.setItem('user', newUser);
        document.querySelector('#user').textContent = 'Current user: ' + newUser;
        this.user = newUser;
    }

    backfillResults() {
        var contestName = document.querySelector('#backfillContest').value;
        var rikishi = document.querySelector('#backfillRikishi').value;
        var picks = this.getPicks();
        picks[contestName] = rikishi;
        localStorage.setItem(this.user, JSON.stringify(picks));
    }

    initialize() {
        var userElement = document.querySelector('#user');
        if (userElement) {
            userElement.textContent = 'Current user: ' + this.user;
        }
    }
}

function initGame() {
  const game = new Game();

  document.querySelector("#startPlayingButton").addEventListener('click', () => game.startPlaying());
  document.querySelector("#switchUserButton").addEventListener('click', () => game.switchUser());
  document.querySelector("#backfillResultsButton").addEventListener('click', () => game.backfillResults());
}

if (typeof window !== 'undefined') {
    window.onload = initGame;
}
```

ChatGPT
It appears that you're using an ES6 export statement in your game.js
file, and the environment you're running this script in doesn't support
ES6 modules natively. This is why the SyntaxError: Unexpected token
'export' error is occurring.

There are several ways to resolve this issue:

Browsers that support ES6 modules: If you're running your script in a
browser that supports ES6 modules (most modern browsers do), you should
include your script with type "module" in your HTML file like this:

```html
<script type="module" src="game.js"></script>
```

Then, in your other scripts or HTML files where you want to use the Game
class, import it as follows:

```javascript
import Game from './game.js';
```

Babel: If you're targeting browsers that don't support ES6 modules,
you'll need to transpile your ES6 code to ES5 using a tool like
[Babel](https://babeljs.io/).

Bundler Tools: If you're using a bundler like
[Webpack](https://webpack.js.org/) or
[Rollup](https://rollupjs.org/guide/en/), you can configure them to
resolve these modules and package them in a format that can be consumed
by the browser.

If you choose to use Babel or a bundler, you will typically set up a
build process that transpiles your code whenever you make changes, so
you always have an up-to-date version of your script that's compatible
with your target environments.

